import React from 'react';
import { CustomLogoIcon, PlusIcon } from '../components/Icons';

// Placeholder component for an empty or filled app slot
const AppSlot: React.FC<{ index: number }> = ({ index }) => (
    <div className="group relative flex flex-col items-center justify-center h-40 w-full rounded-2xl border-2 border-dashed border-gray-300 dark:border-gray-700 bg-white/50 dark:bg-gray-800/50 hover:border-brand-primary/50 hover:bg-white dark:hover:bg-gray-800 hover:shadow-lg transition-all duration-300 cursor-pointer backdrop-blur-sm">
        <div className="h-14 w-14 rounded-full bg-gray-100 dark:bg-gray-700 flex items-center justify-center text-gray-400 group-hover:text-brand-primary group-hover:scale-110 transition-transform duration-300 shadow-inner">
            <PlusIcon className="h-6 w-6" />
        </div>
        <span className="mt-3 text-sm font-medium text-gray-500 dark:text-gray-400 group-hover:text-brand-primary transition-colors">
            Añadir App {index + 1}
        </span>
    </div>
);

const AppsView: React.FC = () => {
  // We need 8 slots to surround the center (3x3 grid minus the center)
  const surroundingSlots = Array.from({ length: 8 }, (_, i) => i);

  return (
    <div className="flex flex-col h-full">
      <div className="mb-6">
        <h1 className="text-3xl font-bold">Aplicaciones</h1>
        <p className="text-light-text-secondary dark:text-dark-text-secondary mt-1">
          Hub central de herramientas y accesos directos.
        </p>
      </div>

      <div className="flex-1 flex items-center justify-center p-4 overflow-y-auto min-h-[600px]">
        <div className="relative w-full max-w-5xl">

            {/* Grid Layout 3x3 */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 md:gap-8">

                {/* Row 1: Slots 0, 1, 2 */}
                {surroundingSlots.slice(0, 3).map(i => (
                    <AppSlot key={i} index={i} />
                ))}

