    <svg className="absolute inset-0 w-full h-full pointer-events-none opacity-30" xmlns="http://www.w3.org/2000/svg">
        <defs>
            <filter id="glow-trace" x="-20%" y="-20%" width="140%" height="140%">
                <feGaussianBlur stdDeviation="1" result="blur" />
                <feComposite in="SourceGraphic" in2="blur" operator="over" />
            </filter>
        </defs>

        {/* Traces connecting center to grid areas approximately */}
        <g stroke="#06b6d4" strokeWidth="1.5" fill="none" filter="url(#glow-trace)" opacity="0.6">
             {/* Left Side Connections */}
            <path d="M 50% 50% L 40% 50% L 35% 20%" />
            <path d="M 50% 50% L 40% 50% L 35% 50% L 20% 50%" />
            <path d="M 50% 50% L 40% 50% L 35% 80%" />

            {/* Right Side Connections */}
            <path d="M 50% 50% L 60% 50% L 65% 20%" />
            <path d="M 50% 50% L 60% 50% L 65% 50% L 80% 50%" />
            <path d="M 50% 50% L 60% 50% L 65% 80%" />

            {/* Nodes */}
            <circle cx="35%" cy="20%" r="2" fill="#06b6d4" />
            <circle cx="20%" cy="50%" r="2" fill="#06b6d4" />
            <circle cx="35%" cy="80%" r="2" fill="#06b6d4" />
            <circle cx="65%" cy="20%" r="2" fill="#06b6d4" />
            <circle cx="80%" cy="50%" r="2" fill="#06b6d4" />
            <circle cx="65%" cy="80%" r="2" fill="#06b6d4" />
        </g>
    </svg>
);

// --- Componente GX Slot (Estilo Octagonal/GX ME) ---
const GXSlot: React.FC<{ item: AppItem; onDelete?: (id: string) => void }> = ({ item, onDelete }) => {
    const [isConnecting, setIsConnecting] = useState(!!item.isNew);

    useEffect(() => {
        if (item.isNew) {
            const timer = setTimeout(() => setIsConnecting(false), 2000);
            return () => clearTimeout(timer);
        }
    }, [item.isNew]);

    // Clases de Grid según el tamaño
    const gridClasses = {
        small: 'col-span-1 row-span-1',
        wide: 'col-span-1 sm:col-span-2 row-span-1',
        tall: 'col-span-1 row-span-2',
        large: 'col-span-1 sm:col-span-2 row-span-2',
    };

    // Altura mínima
    const heightClasses = {
        small: 'h-40',
        wide: 'h-40',
        tall: 'h-80',
        large: 'h-80',
    };

    // Clip-path para el octágono (esquinas recortadas)
    const octagonClip = "polygon(20px 0, calc(100% - 20px) 0, 100% 20px, 100% calc(100% - 20px), calc(100% - 20px) 100%, 20px 100%, 0 calc(100% - 20px), 0 20px)";

    return (
        <div className={`group relative flex items-center justify-center ${gridClasses[item.size]} ${heightClasses[item.size]} p-2 transition-all duration-500 ${isConnecting ? 'scale-95 opacity-0 animate-fade-in' : 'scale-100 opacity-100'}`}>

            {/* Delete Button */}
            {onDelete && (
                <button 
                    onClick={(e) => { e.stopPropagation(); onDelete(item.id); }}
                    className="absolute top-0 right-0 z-30 bg-red-900/80 text-red-200 rounded-full p-1.5 opacity-0 group-hover:opacity-100 transition-opacity hover:bg-red-700 border border-red-500 shadow-lg"
                >
                    <XIcon className="h-3 w-3" />
                </button>
            )}

            {/* Connection Port - Visual element connecting to "circuit" */}
            <div className={`absolute z-0 bg-cyan-900/50 border border-cyan-600/50 w-6 h-2 rounded-sm transition-all duration-300 group-hover:bg-cyan-500 group-hover:shadow-[0_0_10px_rgba(6,182,212,0.8)]
                ${item.id === 'dummy' ? 'hidden' : ''}
                /* Position based on visual flow */
                left-0 top-1/2 -translate-y-1/2
                ${isConnecting ? 'bg-white shadow-[0_0_15px_rgba(255,255,255,0.8)] animate-pulse' : ''}
            `}></div>

            {/* Connection Beam Animation (Simulated) */}
            {isConnecting && (
                <div className="absolute left-0 top-1/2 -translate-y-1/2 w-full h-[2px] bg-cyan-400 z-20 animate-[ping_1s_ease-out_reverse]" style={{ transformOrigin: 'left' }}></div>
            )}

            {/* Main Octagonal Body Wrapper (for border glow) */}
            <div 
                className={`relative z-10 w-full h-full transition-all duration-300 transform group-hover:scale-[1.02] ${isConnecting ? 'brightness-150' : ''}`}
                style={{ filter: 'drop-shadow(0 0 5px rgba(0,0,0,0.5))' }}
            >
                {/* The Shape Background & Border */}
                <div 
                    className={`absolute inset-0 bg-slate-900 border-4 border-slate-700 group-hover:border-cyan-500 transition-colors duration-300 ${isConnecting ? '!border-white shadow-[0_0_20px_rgba(6,182,212,0.6)]' : ''}`}
                    style={{ 
                        clipPath: octagonClip,
                    }}
                >
                    {/* Inner Gradient / Scanline */}
                    <div className="absolute inset-0 bg-gradient-to-br from-slate-800/50 to-slate-900/80 group-hover:from-cyan-900/20 group-hover:to-slate-900/90 transition-colors"></div>

                    {/* Decorative Lines inside */}
                    <div className="absolute bottom-4 left-1/2 -translate-x-1/2 w-1/2 h-[2px] bg-slate-700 group-hover:bg-cyan-500/50 transition-colors"></div>
                    <div className="absolute top-4 left-1/2 -translate-x-1/2 w-8 h-[2px] bg-slate-700 group-hover:bg-cyan-500/50 transition-colors"></div>
                </div>


                {/* Content Container */}
                <div className="absolute inset-0 flex flex-col items-center justify-center z-20 text-center p-6">

                    {/* Icon Container - Hexagon-ish */}
                    <div className="relative mb-3 group-hover:-translate-y-1 transition-transform duration-300">
                        <div className={`absolute inset-0 bg-cyan-500/20 blur-md rounded-full opacity-0 group-hover:opacity-100 transition-opacity ${isConnecting ? 'opacity-100 bg-white/30' : ''}`}></div>
                        <div 
                            className={`relative h-14 w-14 flex items-center justify-center bg-slate-800 border-2 border-slate-600 group-hover:border-cyan-400 group-hover:text-cyan-400 text-slate-500 transition-all duration-300 ${isConnecting ? '!border-white !text-white' : ''}`}
                            style={{ clipPath: "polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%)" }}
                        >
                            <PlusIcon className="h-6 w-6" />
                        </div>
                    </div>

                    <h3 className={`text-sm font-bold text-slate-300 group-hover:text-white tracking-wider uppercase font-mono transition-colors ${isConnecting ? 'text-cyan-300' : ''}`}>
                        {isConnecting ? 'CONNECTING...' : item.label}
                    </h3>

                    <div className="mt-2 flex items-center gap-2">
                        <div className="h-1 w-8 bg-slate-700 rounded-full overflow-hidden">
                            <div className={`h-full bg-cyan-500 w-1/2 group-hover:w-full transition-all duration-500 ${isConnecting ? 'w-full animate-pulse' : ''}`}></div>
                        </div>
                        <span className="text-[9px] text-slate-500 font-mono group-hover:text-cyan-400">
                            {isConnecting ? 'INIT' : `${Math.floor(Math.random() * 100)}%`}
                        </span>
                    </div>
                </div>
            </div>
        </div>
    );
};

