            <div className="absolute left-0 top-1/2 -translate-y-1/2 w-6 h-1 bg-cyan-500/50"></div>
            <div className="absolute right-0 top-1/2 -translate-y-1/2 w-6 h-1 bg-cyan-500/50"></div>
        </div>
    </div>
);

const AppsView: React.FC = () => {
    // Estado inicial
    const [apps, setApps] = useState<AppItem[]>([
        { id: '1', size: 'small', label: 'Mods', isEmpty: true },
        { id: '2', size: 'wide', label: 'Configuración', isEmpty: true },
        { id: '3', size: 'small', label: 'Tienda', isEmpty: true },
        { id: '4', size: 'tall', label: 'Análisis', isEmpty: true },
        { id: '5', size: 'small', label: 'Perfil', isEmpty: true },
        { id: '6', size: 'small', label: 'Ayuda', isEmpty: true },
    ]);

    const handleAddApp = () => {
        const sizes: SlotSize[] = ['small', 'small', 'wide', 'tall']; 
        const randomSize = sizes[Math.floor(Math.random() * sizes.length)];

        const newApp: AppItem = {
            id: Date.now().toString(),
            size: randomSize,
            label: `App ${apps.length + 1}`,
            isEmpty: true,
            isNew: true,
        };
        setApps(prev => [...prev, newApp]);
    };

    const handleDeleteApp = (id: string) => {
        setApps(apps.filter(a => a.id !== id));
    };

    // Calculate midpoint to split apps around the core
    const halfIndex = Math.ceil(apps.length / 2);
    const leftApps = apps.slice(0, halfIndex);
    const rightApps = apps.slice(halfIndex);

    return (
        <div className="flex flex-col h-full bg-slate-950 text-cyan-50 rounded-xl overflow-hidden relative border border-slate-800 shadow-2xl font-sans">
            {/* Header */}
            <div className="p-6 border-b border-slate-800 bg-slate-900/90 relative z-20 flex justify-between items-end backdrop-blur-sm">
                <div>
                    <h1 className="text-4xl font-black tracking-tighter text-white" style={{ textShadow: '0 0 15px rgba(6,182,212,0.3)' }}>
                        <span className="text-cyan-500">GX</span> APPS
                    </h1>
                    <p className="text-slate-400 mt-1 font-medium text-sm uppercase tracking-widest">
                        Hub de Aplicaciones 2.0
                    </p>
                </div>
                <div className="hidden sm:block text-right font-mono text-[10px] text-cyan-800 bg-black/20 p-2 rounded border border-cyan-900/30">
                    SYSTEM_READY<br/>
                    CORE_ONLINE
                </div>
            </div>

            {/* Scrollable Grid Area */}
            <div className="flex-1 overflow-y-auto p-6 relative min-h-[600px] scrollbar-hide bg-[#0B0F17]">
                <CircuitBackground />

                {/* Bento Grid Layout */}
                {/* justify-center and content-center help keep the core somewhat central in the viewport if grid is sparse */}
                <div className="relative z-10 w-full max-w-7xl mx-auto grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-6 auto-rows-[10rem] grid-flow-dense p-4 justify-center content-center min-h-full">

                    {/* Render first half of apps */}
                    {leftApps.map((app) => (
                        <GXSlot key={app.id} item={app} onDelete={handleDeleteApp} />
                    ))}

                    {/* Central GX Core - Centered in logic by placing it in between arrays */}
                    <GXCpuCore />

                    {/* Render second half of apps */}
                    {rightApps.map((app) => (
                        <GXSlot key={app.id} item={app} onDelete={handleDeleteApp} />
                    ))}

                </div>
            </div>

            {/* Floating Add Button */}
            <button 
                onClick={handleAddApp}
                className="absolute bottom-8 right-8 z-50 h-16 w-16 bg-cyan-600 hover:bg-cyan-500 text-white rounded-full shadow-[0_0_20px_rgba(6,182,212,0.6)] flex items-center justify-center transition-all hover:scale-110 active:scale-95 group border-4 border-slate-900 outline outline-2 outline-cyan-500"
                title="Añadir Módulo"
            >
                <PlusIcon className="h-8 w-8 group-hover:rotate-90 transition-transform duration-300" />
            </button>
        </div>
    );
};

export default AppsView;
